/// Default English strings for bottom sheets.
abstract final class M3EBottomSheetStrings {
  const M3EBottomSheetStrings._();

  /// Drag handle label.
  static const String dragHandle = 'Drag handle';

  /// Expand action.
  static const String expand = 'Expand';

  /// Collapse action.
  static const String collapse = 'Collapse';

  /// Dismiss action.
  static const String dismiss = 'Dismiss';

  /// Close action.
  static const String close = 'Close';

  /// Preview height value.
  static const String preview = 'Preview';

  /// Collapsed height value.
  static const String collapsed = 'Collapsed';

  /// Expanded height value.
  static const String expanded = 'Expanded';

  /// Full-screen height value.
  static const String fullScreen = 'Full screen';
}
